    if not my_matrix or not all(my_matrix):
        return False
    n = len(my_matrix)
    if any(len(row) != n for row in my_matrix):
        return False

    # Target sum is the sum of the first row
    target = sum(my_matrix[0])

    # Check all rows
    for row in my_matrix:
        if sum(row) != target:
            return False

    # Check all columns
    for col in range(n):
        if sum(my_matrix[row][col] for row in range(n)) != target:
            return False

    # Check main diagonal (top-left to bottom-right)
    if sum(my_matrix[i][i] for i in range(n)) != target:
        return False

    # Check secondary diagonal (top-right to bottom-left)
    if sum(my_matrix[i][n - 1 - i] for i in range(n)) != target:
