    Return True if list B is a contiguous sublist of list A, otherwise False.
    """
    # An empty B is always a sublist
    if not B:
        return True

    len_a, len_b = len(A), len(B)

    # If B is longer than A, it cannot be a sublist
    if len_b > len_a:
        return False

    # Slide a window of length len_b over A
    for start in range(len_a - len_b + 1):
        if A[start:start + len_b] == B:
            return True

